{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 차 업무 적용형 최소 RAG 시제품 구축 로드맵",
  "summary": "사용자의 Python 경험과 2주(주 3시간)의 제한된 시간을 고려하여, 이론 중심이 아닌 '가상 규정 3건'을 데이터로 활용한 최소 RAG 시제품 구축에 집중합니다. 검색 성공, 근거 누락, 답변 불가(거절)의 3가지 케이스를 명확히 구분하는 로직 구현을 목표로 하며, 검색된 무료 Microsoft Learn 자료를 활용하여 비용 부담 없이 학습을 진행합니다. 규정 관련 지원금은 미확정 상태이므로 현금 예산(20,000원) 내에서 무료 리소스만 활용하도록 계획했습니다.",
  "project_goal": "가상 규정 3건을 데이터로 하여 질문 5건에 대해 근거를 표시하고, 근거가 없는 질문은 '답변 불가'로 구분하는 최소 RAG 시제품 구현",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 이해 및 데이터 준비",
      "duration": "1주 (3시간)",
      "focus": "RAG의 기본 흐름(Chunking, Embedding, Retrieval, Generation) 이해 및 가상 규정 3건의 텍스트 데이터 전처리"
    },
    {
      "step": 2,
      "title": "최소 RAG 파이프라인 구현 및 검증",
      "duration": "1주 (3시간)",
      "focus": "벡터 DB 연동, 검색 로직 구현, LLM 프롬프트 설계 및 5개 질문 케이스(성공/누락/불가) 테스트"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기반 구축 및 데이터 전처리",
      "duration": "1주",
      "focus_goal": "RAG 개념 정립 및 가상 규정 데이터의 청킹(Chunking) 및 임베딩(Embedding) 파이프라인 구축",
      "key_actions": [
        "Microsoft Learn 'Microsoft Foundry를 사용하여 생성 AI 모델 성능 최적화' 모듈을 통해 RAG 개념 및 최적화 전략 학습",
        "가상 규정 3건의 텍스트를 의미 단위로 청킹(Chunking) 처리",
        "임베딩 모델 선택 및 벡터 데이터 생성 스크립트 작성 (Python)"
      ],
      "deliverables": [
        "가상 규정 3건의 청킹된 데이터셋",
        "임베딩 생성 및 벡터 저장소(예: ChromaDB 등 로컬 DB) 초기화 코드"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "시제품 구현 및 케이스별 검증",
      "duration": "1주",
      "focus_goal": "검색 및 생성 로직 구현을 통해 5개 질문의 응답 품질 검증 및 근거 표시/거절 로직 완성",
      "key_actions": [
        "Microsoft Learn '추적을 사용하여 생성형 AI 앱 분석 및 디버그' 모듈을 참고하여 검색-생성 흐름 디버깅 방법 학습",
        "검색된 문단과 질문을 결합한 프롬프트 설계 (시스템 메시지 포함)",
        "질문 5건 테스트: 1) 근거 있는 질문, 2) 근거 부분 누락 질문, 3) 근거 없는 질문(거절) 등 케이스별 응답 확인",
        "응답에 근거 출처(문단 ID 등)를 표시하는 로직 구현"
      ],
      "deliverables": [
        "최소 RAG 시제품 실행 스크립트",
        "5개 질문별 테스트 결과 리포트 (검색 성공/근거 누락/답변 불가 구분 포함)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
  "regulation_citations": [],
  "clarification_questions": []
}
